import {setMfeUrlPrefix, getMfeUrlPrefix} from '../http';

describe('mfe-url-prefix tests', () => {

  it('should be able to set the prefix and then get it.', (done) => {
    setMfeUrlPrefix('mfe-id-1', 'mfe-1-prefix');


    getMfeUrlPrefix('mfe-id-1').then((prefix: string) => {
      expect(prefix).toBe('mfe-1-prefix');
      done();
    });
  });

  it('should be able to get the prefix and then set it.', (done) => {
    getMfeUrlPrefix('mfe-id-1').then((prefix: string) => {
      expect(prefix).toBe('mfe-1-prefix');
      done();
    });

    setMfeUrlPrefix('mfe-id-1', 'mfe-1-prefix');
  });

  it('should be able to get and set multiple prefixes', (done) => {
    setMfeUrlPrefix('mfe-id-1', 'mfe-1-prefix');
    setMfeUrlPrefix('mfe-id-2', 'mfe-2-prefix');

    Promise.all([
      getMfeUrlPrefix('mfe-id-1'),
      getMfeUrlPrefix('mfe-id-2')
    ]).then(([prefix1, prefix2]: [string, string]) => {
      expect(prefix1).toBe('mfe-1-prefix');
      expect(prefix2).toBe('mfe-2-prefix');
      done();
    });
  });

  it('should be able to get and set multiple prefixes in multiple orders', (done) => {
    setMfeUrlPrefix('mfe-id-2', 'mfe-2-prefix');

    Promise.all([
      getMfeUrlPrefix('mfe-id-1'),
      getMfeUrlPrefix('mfe-id-2')
    ]).then(([prefix1, prefix2]: [string, string]) => {
      expect(prefix1).toBe('mfe-1-prefix');
      expect(prefix2).toBe('mfe-2-prefix');
      done();
    });

    setMfeUrlPrefix('mfe-id-1', 'mfe-1-prefix');
  });

  it('should not be able to set the prefix more than once', (done) => {

    const originalConsoleError = console.error;
    console.error = function(value: any): void {
      expect(value).toBe('You cannot set the MfeUrlPrefix for the Mfe with id: \'mfe-id-1\' more than once in an application.');
    };
    setMfeUrlPrefix('mfe-id-1', 'mfe-1-prefix');
    setMfeUrlPrefix('mfe-id-1', 'mfe-1-prefix changed');

    console.error = originalConsoleError;


    getMfeUrlPrefix('mfe-id-1').then((prefix: string) => {
      expect(prefix).toBe('mfe-1-prefix');
      done();
    });
  });
});